17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.DayOfWeek;
23	import java.time.LocalDate;
24	import java.util.ArrayList;
25	import java.util.Collection;
26	import java.util.Comparator;
27	import java.util.List;
28	import java.util.Locale;
29	import java.util.Map;
30	import java.util.regex.Pattern;
31	
32	import org.slf4j.Logger;
33	import org.slf4j.LoggerFactory;
34	import org.springframework.http.HttpHeaders;
35	import org.springframework.http.HttpStatus;
36	import org.springframework.http.ResponseEntity;
37	import org.springframework.samples.petclinic.mapper.OwnerLocality;
38	import org.springframework.samples.petclinic.mapper.OwnerMapper;
39	import org.springframework.samples.petclinic.mapper.PetMapper;
40	import org.springframework.samples.petclinic.mapper.VisitMapper;
41	import org.springframework.samples.petclinic.model.Owner;
42	import org.springframework.samples.petclinic.model.Pet;
43	import org.springframework.samples.petclinic.model.Visit;
44	import org.springframework.samples.petclinic.rest.api.OwnersApi;
45	import org.springframework.samples.petclinic.rest.controller.CityOwnerLimitExceededException;
46	import org.springframework.samples.petclinic.rest.controller.DailyOwnerLimitExceededException;
47	import org.springframework.samples.petclinic.rest.controller.DuplicateIdentityException;
48	import org.springframework.samples.petclinic.rest.controller.FutureRegistrationDateException;
49	import org.springframework.samples.petclinic.rest.controller.HouseholdDuplicateException;
50	import org.springframework.samples.petclinic.rest.controller.InvalidEmailException;
51	import org.springframework.samples.petclinic.rest.controller.InvalidPostcodeException;
52	import org.springframework.samples.petclinic.rest.controller.InvalidTelephoneException;
53	import org.springframework.samples.petclinic.rest.controller.RequiredFieldsMissingException;
54	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
55	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
56	import org.springframework.samples.petclinic.rest.dto.PetDto;
57	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
58	import org.springframework.samples.petclinic.rest.dto.VisitDto;
59	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
60	import org.springframework.samples.petclinic.service.ClinicService;
61	import org.springframework.security.access.prepost.PreAuthorize;
62	import org.springframework.web.bind.annotation.CrossOrigin;
63	import org.springframework.web.bind.annotation.RequestMapping;
64	import org.springframework.web.bind.annotation.RestController;
65	import org.springframework.web.util.UriComponentsBuilder;
66	
67	import jakarta.transaction.Transactional;
68	
69	/**
70	 * @author Vitaliy Fedoriv
71	 */
72	
73	@RestController
74	@CrossOrigin(exposedHeaders = "errors, content-type")
75	@RequestMapping("/api")
76	public class OwnerRestControllerV1 implements OwnersApi {
77	
78	    /**
79	     * Pragmatic syntactic check for an email address: a non-empty local part, a single {@code @}, and a
80	     * domain with at least one dot and a two-or-more-letter final label. Whitespace is not permitted.
81	     */
82	    private static final Pattern EMAIL_PATTERN =
83	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@.]{2,}$");
84	
85	    /**
86	     * Dedicated audit logger. Successful side-effecting operations (such as creating an owner) emit a
87	     * line here so audit trails can be captured independently of application logging.
88	     */
89	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
90	
91	    private final ClinicService clinicService;
92	
93	    private final OwnerMapper ownerMapper;
94	
95	    private final PetMapper petMapper;
96	
97	    private final VisitMapper visitMapper;
98	
99	    public OwnerRestControllerV1(ClinicService clinicService,
100	                                 OwnerMapper ownerMapper,
101	                                 PetMapper petMapper,
102	                                 VisitMapper visitMapper) {
103	        this.clinicService = clinicService;
104	        this.ownerMapper = ownerMapper;
105	        this.petMapper = petMapper;
106	        this.visitMapper = visitMapper;
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
112	        Collection<Owner> owners;
113	        if (lastName != null) {
114	            owners = this.clinicService.findOwnerByLastName(lastName);
115	        } else {
116	            owners = this.clinicService.findAllOwners();
117	        }
118	        if (owners.isEmpty()) {
119	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
120	        }
121	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
127	        Owner owner = this.clinicService.findOwnerById(ownerId);
128	        if (owner == null) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
137	        rejectMissingOrBlankFields(ownerFieldsDto);
138	        HttpHeaders headers = new HttpHeaders();
139	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
140	        owner.setAddress(normalizeAddress(owner.getAddress()));
141	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
142	        owner.setEmail(normalizeEmail(owner.getEmail()));
143	        validatePostcode(owner.getPostcode(), owner.getCity());
144	        rejectFutureRegistrationDate(owner.getRegistrationDate());
145	        if (owner.getRegistrationDate() == null) {
146	            owner.setRegistrationDate(LocalDate.now());
147	        }
148	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
149	        rejectDailyLimitReached(owner.getRegistrationDate());
150	        rejectCityAtCapacity(owner.getCity());
151	        owner.setHouseholdId(computeHouseholdId(owner));
152	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
153	        rejectDuplicateIdentity(owner);
154	        if (!sharesHousehold) {
155	            rejectHouseholdDuplicate(owner);
156	        }
157	        assignPossibleDuplicate(owner, sharesHousehold);
158	        owner.setCustomerCode(generateCustomerCode(owner));
159	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
160	        owner.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
161	        this.clinicService.saveOwner(owner);
162	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
163	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
164	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
165	        headers.setLocation(UriComponentsBuilder.newInstance()
166	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
167	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
173	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
174	        if (currentOwner == null) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        currentOwner.setAddress(ownerFieldsDto.getAddress());
178	        currentOwner.setCity(ownerFieldsDto.getCity());
179	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
180	        currentOwner.setLastName(ownerFieldsDto.getLastName());
181	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
182	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
183	        this.clinicService.saveOwner(currentOwner);
184	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Transactional
189	    @Override
190	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
191	        Owner owner = this.clinicService.findOwnerById(ownerId);
192	        if (owner == null) {
193	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	        }
195	        this.clinicService.deleteOwner(owner);
196	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
197	    }
198	
199	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
200	    @Override
201	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
202	        Owner owner = this.clinicService.findOwnerById(ownerId);
203	        if (owner == null) {
204	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
205	        }
206	        HttpHeaders headers = new HttpHeaders();
207	        Pet pet = petMapper.toPet(petFieldsDto);
208	        owner.setId(ownerId);
209	        pet.setOwner(owner);
210	        pet.getType().setName(null);
211	        this.clinicService.savePet(pet);
212	        PetDto petDto = petMapper.toPetDto(pet);
213	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
214	            .buildAndExpand(pet.getId()).toUri());
215	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
216	    }
217	
218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
221	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
222	        if (currentOwner != null) {
223	            Pet currentPet = this.clinicService.findPetById(petId);
224	            if (currentPet != null) {
225	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
226	                currentPet.setName(petFieldsDto.getName());
227	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
228	                this.clinicService.savePet(currentPet);
229	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
230	            }
231	        }
232	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
233	    }
234	
235	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
236	    @Override
237	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
238	        HttpHeaders headers = new HttpHeaders();
239	        Visit visit = visitMapper.toVisit(visitFieldsDto);
240	        Pet pet = new Pet();
241	        pet.setId(petId);
242	        visit.setPet(pet);
243	        this.clinicService.saveVisit(visit);
244	        VisitDto visitDto = visitMapper.toVisitDto(visit);
245	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
246	            .buildAndExpand(visit.getId()).toUri());
247	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
248	    }
249	
250	
251	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
252	    @Override
253	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
254	        Owner owner = this.clinicService.findOwnerById(ownerId);
255	        if (owner != null) {
256	            Pet pet = owner.getPet(petId);
257	            if (pet != null) {
258	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
259	            }
260	        }
261	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
262	    }
263	
264	    /**
265	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
266	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
267	     *
268	     * @param fields the submitted owner fields
269	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
270	     *                                        {@code null} or blank, or if address is blank after
271	     *                                        normalization
272	     */
273	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
274	        List<String> missing = new ArrayList<>();
275	        if (isBlank(fields.getFirstName())) {
276	            missing.add("firstName");
277	        }
278	        if (isBlank(fields.getLastName())) {
279	            missing.add("lastName");
280	        }
281	        if (isBlank(normalizeAddress(fields.getAddress()))) {
282	            missing.add("address");
283	        }
284	        if (isBlank(fields.getCity())) {
285	            missing.add("city");
286	        }
287	        if (isBlank(fields.getTelephone())) {
288	            missing.add("telephone");
289	        }
290	        if (!missing.isEmpty()) {
291	            throw new RequiredFieldsMissingException(missing);
292	        }
293	    }
294	
295	    private boolean isBlank(String value) {
296	        return value == null || value.isBlank();
297	    }
298	
299	    /**
300	     * Inclusive 4-digit postcode ranges permitted per city region, keyed by the region derived from the
301	     * city via {@link OwnerLocality}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region absent from
302	     * this table (i.e. {@code "UNKNOWN"}) imposes no range constraint, so any 4-digit postcode is accepted.
303	     */
304	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
305	        "NSW", new int[] {2000, 2099},
306	        "VIC", new int[] {3000, 3099},
307	        "QLD", new int[] {4000, 4099});
308	
309	    /**
310	     * Validates an owner's {@code postcode} when present. Postcode is optional: a {@code null} value is
311	     * accepted and left absent, keeping the create contract backward-compatible. When supplied it must be
312	     * a 4-digit value, and it must fall within the inclusive range for the city's region (NSW 2000-2099,
313	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
314	     *
315	     * @param postcode the submitted postcode, or {@code null} when omitted
316	     * @param city the owner's city, used to derive the region whose range constrains the postcode
317	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for the
318	     *                                  city's region
319	     */
320	    private void validatePostcode(String postcode, String city) {
321	        if (postcode == null) {
322	            return;
323	        }
324	        if (!postcode.matches("[0-9]{4}")) {
325	            throw new InvalidPostcodeException(postcode);
326	        }
327	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.of(city));
328	        if (range == null) {
329	            return;
330	        }
331	        int value = Integer.parseInt(postcode);
332	        if (value < range[0] || value > range[1]) {
333	            throw new InvalidPostcodeException(postcode);
334	        }
335	    }
336	
337	    /**
338	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
339	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
340	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
341	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
342	     * <p>
343	     * Where a per-country rule is defined the national-number length is validated against the country
344	     * code: {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP)
345	     * requires exactly 10.
346	     *
347	     * @param telephone the raw telephone value from the request
348	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
349	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
350	     */
351	    private String normalizeTelephone(String telephone) {
352	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
353	        String digits;
354	        if (cleaned.startsWith("+")) {
355	            digits = cleaned.substring(1);
356	        } else {
357	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
358	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
359	            digits = "61" + national;
360	        }
361	        if (!digits.matches("[0-9]{8,15}")) {
362	            throw new InvalidTelephoneException(cleaned);
363	        }
364	        // Validate the national-number length against the country code where a rule is defined.
365	        if (digits.startsWith("61") && digits.length() - 2 != 9) {
366	            throw new InvalidTelephoneException(cleaned);
367	        }
368	        if (digits.startsWith("1") && digits.length() - 1 != 10) {
369	            throw new InvalidTelephoneException(cleaned);
370	        }
371	        return "+" + digits;
372	    }
373	
374	    /**
375	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
376	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
377	     * lower-cased.
378	     *
379	     * @param email the raw email value from the request, or {@code null} if omitted
380	     * @return the lower-cased email, or {@code null} if none was supplied
381	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
382	     */
383	    private String normalizeEmail(String email) {
384	        if (email == null) {
385	            return null;
386	        }
387	        String trimmed = email.strip();
388	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
389	            throw new InvalidEmailException(email);
390	        }
391	        return trimmed.toLowerCase(Locale.ROOT);
392	    }
393	
394	    /**
395	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
396	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
397	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
398	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
399	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
400	     *
401	     * @param address the raw address value from the request (may be {@code null})
402	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
403	     */
404	    private String normalizeAddress(String address) {
405	        if (address == null) {
406	            return "";
407	        }
408	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
409	        if (collapsed.isEmpty()) {
410	            return "";
411	        }
412	        String[] tokens = collapsed.split(" ");
413	        StringBuilder sb = new StringBuilder(collapsed.length());
414	        for (int i = 0; i < tokens.length; i++) {
415	            if (i > 0) {
416	                sb.append(' ');
417	            }
418	            sb.append(expandAddressAbbreviation(tokens[i]));
419	        }
420	        return sb.toString();
421	    }
422	
423	    /**
424	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
425	     * returns the token unchanged when it is not a recognised abbreviation.
426	     *
427	     * @param token an upper-cased whole-word address token
428	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
429	     */
430	    private String expandAddressAbbreviation(String token) {
431	        return switch (token) {
432	            case "ST" -> "STREET";
433	            case "RD" -> "ROAD";
434	            case "AVE" -> "AVENUE";
435	            default -> token;
436	        };
437	    }
438	
439	    /**
440	     * Builds the customer code assigned to a newly created owner, formatted {@code '<REGION>-<HASH8>'}
441	     * where {@code REGION} is the region derived from the owner's postcode (falling back to the city when
442	     * the postcode resolves to no known region), the same derivation that yields the owner's locality, and
443	     * {@code HASH8} is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
444	     * normalized telephone concatenated with the owner's last name (e.g. {@code 'NSW-1A2B3C4D'}). Unlike the
445	     * former per-city sequence, the code is a pure function of the owner's own region and identity, so no
446	     * sequence number is assigned.
447	     *
448	     * @param owner the owner being created, with normalized telephone and postcode already set
449	     * @return the assigned customer code
450	     */
451	    private String generateCustomerCode(Owner owner) {
452	        String region = OwnerLocality.of(owner.getCity(), owner.getPostcode());
453	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
454	            .substring(0, 8).toUpperCase(Locale.ROOT);
455	        return region + "-" + hash8;
456	    }
457	
458	    /**
459	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
460	     *
461	     * @param value the value to hash
462	     * @return the 64-character lower-case hex SHA-256 digest
463	     */
464	    private String sha256Hex(String value) {
465	        try {
466	            byte[] digest = MessageDigest.getInstance("SHA-256")
467	                .digest(value.getBytes(StandardCharsets.UTF_8));
468	            StringBuilder sb = new StringBuilder(digest.length * 2);
469	            for (byte b : digest) {
470	                sb.append(String.format("%02x", b));
471	            }
472	            return sb.toString();
473	        } catch (NoSuchAlgorithmException e) {
474	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
475	        }
476	    }
477	
478	    /**
479	     * Counts how many existing owners already share the given first name and last name, compared
480	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
481	     * owner being created.
482	     *
483	     * @param firstName the first name of the owner being created
484	     * @param lastName the last name of the owner being created
485	     * @return the number of existing owners with the same first and last name (case-insensitively)
486	     */
487	    private int countNamesakes(String firstName, String lastName) {
488	        return (int) this.clinicService.findAllOwners().stream()
489	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
490	                && lastName.equalsIgnoreCase(existing.getLastName()))
491	            .count();
492	    }
493	
494	    /**
495	     * The maximum number of owners permitted in a single city. A create request whose city already
496	     * holds this many owners is rejected.
497	     */
498	    private static final int CITY_OWNER_LIMIT = 50;
499	
500	    /**
501	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
502	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
503	     * differing only in the casing of their city share one capacity pool. The count is taken before the
504	     * new owner is persisted, so it excludes the owner being created.
505	     *
506	     * @param city the city of the owner being created
507	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
508	     */
509	    private void rejectCityAtCapacity(String city) {
510	        long existing = this.clinicService.findAllOwners().stream()
511	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
512	            .count();
513	        if (existing >= CITY_OWNER_LIMIT) {
514	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
515	        }
516	    }
517	
518	    /**
519	     * The maximum number of owners permitted to be created in a single day. A create request whose
520	     * registration date already holds this many owners is rejected.
521	     */
522	    private static final int DAILY_OWNER_LIMIT = 100;
523	
524	    /**
525	     * Rejects a create request when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
526	     * on the same day, compared by {@code registrationDate}. The count is taken before the new owner is
527	     * persisted, so it excludes the owner being created.
528	     *
529	     * @param registrationDate the registration date of the owner being created
530	     * @throws DailyOwnerLimitExceededException if the day already holds the maximum number of owners
531	     */
532	    /**
533	     * Adjusts an effective registration date so that it always falls on a business day. When the given
534	     * date is a Saturday or Sunday it is rolled forward to the following Monday; a weekday is returned
535	     * unchanged. This applies equally to a date supplied in the request and to a date defaulted to the
536	     * server date, and the adjusted value is what becomes the owner's {@code registrationDate}, so every
537	     * value derived from it (the membership number's year segment, the daily create-limit count) uses the
538	     * business-day-adjusted date.
539	     *
540	     * @param date the effective registration date, supplied or defaulted
541	     * @return the same date when it is a weekday, otherwise the next Monday
542	     */
543	    private LocalDate rollToBusinessDay(LocalDate date) {
544	        DayOfWeek day = date.getDayOfWeek();
545	        if (day == DayOfWeek.SATURDAY) {
546	            return date.plusDays(2);
547	        }
548	        if (day == DayOfWeek.SUNDAY) {
549	            return date.plusDays(1);
550	        }
551	        return date;
552	    }
553	
554	    /**
555	     * The number of owners that must already exist for a given day before a further create is flagged as a
556	     * bulk sign-up surge. When more than this many owners already share the new owner's registration date,
557	     * the created owner carries {@code bulkSignupWarning = true}.
558	     */
559	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
560	
561	    /**
562	     * Determines whether the owner being created lands on a day that already holds a bulk sign-up surge,
563	     * i.e. more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already share its {@code registrationDate}.
564	     * The count is taken before the new owner is persisted, so it excludes the owner being created, mirroring
565	     * the daily create-limit rule's accumulation path.
566	     *
567	     * @param registrationDate the registration date of the owner being created
568	     * @return {@code true} when more than 80 owners were already created on that day, otherwise {@code false}
569	     */
570	    private boolean isBulkSignupDay(LocalDate registrationDate) {
571	        long existing = this.clinicService.findAllOwners().stream()
572	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
573	            .count();
574	        return existing > BULK_SIGNUP_WARNING_THRESHOLD;
575	    }
576	
577	    /**
578	     * Rejects a create request whose supplied {@code registrationDate} is later than the server date. A
579	     * registration cannot be dated in the future. The check applies only to a date supplied in the request;
580	     * a {@code null} value (which is later defaulted to the server date) is accepted, and the comparison is
581	     * made against the supplied value before any business-day adjustment.
582	     *
583	     * @param registrationDate the registration date supplied in the request, or {@code null} when omitted
584	     * @throws FutureRegistrationDateException if a supplied registration date is later than the server date
585	     */
586	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
587	        if (registrationDate == null) {
588	            return;
589	        }
590	        LocalDate today = LocalDate.now();
591	        if (registrationDate.isAfter(today)) {
592	            throw new FutureRegistrationDateException(registrationDate, today);
593	        }
594	    }
595	
596	    private void rejectDailyLimitReached(LocalDate registrationDate) {
597	        long existing = this.clinicService.findAllOwners().stream()
598	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
599	            .count();
600	        if (existing >= DAILY_OWNER_LIMIT) {
601	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
602	        }
603	    }
604	
605	    /**
606	     * Rejects a create request whose owner collides with an existing owner on the single derived
607	     * {@code identityKey}. This one key consolidates the former separate telephone, email and household
608	     * duplicate checks: the create is rejected only when the new owner's WHOLE identity key exactly equals
609	     * an existing owner's. Because the (normalized) telephone is part of the key, two members of the same
610	     * household (same {@code householdId}) with different telephones have different keys and are both
611	     * allowed; only an exact full-key match is a duplicate. The owner's {@code householdId} has already
612	     * been computed (deterministically from the last name and postcode) before this check runs, so the
613	     * key compared here is the same one that is later returned.
614	     *
615	     * @param owner the owner being created, with normalized fields and its computed {@code householdId} set
616	     * @throws DuplicateIdentityException if an existing owner has the same identity key
617	     */
618	    private void rejectDuplicateIdentity(Owner owner) {
619	        String key = identityKey(owner);
620	        boolean taken = this.clinicService.findAllOwners().stream()
621	            .anyMatch(existing -> key.equals(identityKey(existing)));
622	        if (taken) {
623	            throw new DuplicateIdentityException(key);
624	        }
625	    }
626	
627	    /**
628	     * Flags a soft (possible) duplicate on the owner being created. A soft match is an existing owner that,
629	     * while not a hard {@code identityKey} duplicate (that stronger check has already run), shares this
630	     * owner's last name (compared case-insensitively) and exact postcode but carries a different normalized
631	     * telephone. When at least one such owner exists, {@code possibleDuplicate} is set {@code true} and
632	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match, for
633	     * determinism); otherwise {@code possibleDuplicate} is set {@code false} and no match id is recorded. A
634	     * new owner with no postcode has nothing to match on and is never a possible duplicate.
635	     * <p>
636	     * A declared household member ({@code sharesHousehold}) is never flagged: sharing a last name and
637	     * postcode is now exactly the household key, so such an owner is a known household member rather than
638	     * a suspected duplicate.
639	     *
640	     * @param owner the owner being created, with normalized telephone and validated postcode already set
641	     * @param sharesHousehold whether the create declared the owner a household member
642	     */
643	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
644	        Integer matchId = null;
645	        if (!sharesHousehold && owner.getPostcode() != null) {
646	            matchId = this.clinicService.findAllOwners().stream()
647	                .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
648	                    && owner.getPostcode().equals(existing.getPostcode())
649	                    && !telephonesEqual(owner.getTelephone(), existing.getTelephone()))
650	                .map(Owner::getId)
651	                .filter(id -> id != null)
652	                .min(Comparator.naturalOrder())
653	                .orElse(null);
654	        }
655	        owner.setPossibleDuplicate(matchId != null);
656	        owner.setPossibleDuplicateOf(matchId);
657	    }
658	
659	    private boolean telephonesEqual(String a, String b) {
660	        return a == null ? b == null : a.equals(b);
661	    }
662	
663	    /**
664	     * Derives an owner's {@code identityKey}: the normalized telephone, the email (or an empty string when
665	     * absent) and the household id (or an empty string when absent), joined by {@code '|'} in that order
666	     * (e.g. {@code '+61412345678||a1b2c3d4e5f6a7b8'} for an owner with no email but a shared household).
667	     * Telephone and email are stored already normalized, so the stored values are used directly.
668	     *
669	     * @param owner the owner whose identity key is being derived
670	     * @return the owner's identity key
671	     */
672	    private String identityKey(Owner owner) {
673	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
674	        String email = owner.getEmail() == null ? "" : owner.getEmail();
675	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
676	        return telephone + "|" + email + "|" + householdId;
677	    }
678	
679	    /**
680	     * Computes the owner's deterministic {@code householdId}: the first 12 hex characters of the SHA-256
681	     * digest of {@code '<normalizedLastName>|<postcode>'}, where the last name is normalized with
682	     * {@link #normalizeForComparison} and an absent postcode contributes an empty string. Because the
683	     * identifier is a pure function of last name and postcode, any two owners sharing those values share
684	     * the household automatically, with no cross-owner mutation. The value is assigned to every owner,
685	     * whether or not {@code sharesHousehold} was requested.
686	     *
687	     * @param owner the owner being created, with its validated postcode already set
688	     * @return the deterministic household identifier
689	     */
690	    private String computeHouseholdId(Owner owner) {
691	        String normalizedLastName = normalizeForComparison(owner.getLastName());
692	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
693	        return sha256Hex(normalizedLastName + "|" + postcode).substring(0, 12);
694	    }
695	
696	    /**
697	     * Rejects a create request whose owner would join an existing household without declaring it. The
698	     * household is keyed on the computed {@code householdId} (derived from last name and postcode), so any
699	     * existing owner sharing that identifier is already a member of the same household; a further owner is a
700	     * household duplicate. The check is bypassed when the request opted in via {@code sharesHousehold}, in
701	     * which case the owner is created as a declared household member. The (stronger) exact identity-key
702	     * check has already run, so a full duplicate is rejected regardless of {@code sharesHousehold}.
703	     *
704	     * @param owner the owner being created, with its computed {@code householdId} already assigned
705	     * @throws HouseholdDuplicateException if an existing owner already shares the household
706	     */
707	    private void rejectHouseholdDuplicate(Owner owner) {
708	        String householdId = owner.getHouseholdId();
709	        boolean shared = this.clinicService.findAllOwners().stream()
710	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
711	        if (shared) {
712	            throw new HouseholdDuplicateException(householdId);
713	        }
714	    }
715	
716	    /**
717	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
718	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
719	     * lower-cased.
720	     *
721	     * @param value the raw value to normalize (may be {@code null})
722	     * @return the normalized value, or an empty string when {@code value} is {@code null}
723	     */
724	    private String normalizeForComparison(String value) {
725	        if (value == null) {
726	            return "";
727	        }
728	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
729	    }
730	}
